function resolveDifficulty(code: string, category: string): number {
  if (code.includes('199') || code.includes('198') || code.includes('197')) return 8.8; // Thesis / Practicum
  if (code.includes('195') || code.includes('196')) return 8.0;
  if (code.startsWith('CHM') || code.startsWith('PHY') || code.startsWith('MAT') || code.startsWith('CAL')) return 7.5;
  if (code.startsWith('BIO') || code.startsWith('STT') || code.startsWith('GEN')) return 7.0;
  if (code.startsWith('PED') || code.startsWith('NST')) return 2.2;
  if (code.startsWith('GEC') || code.startsWith('FPE') || code.startsWith('HAL') || code.startsWith('FIL')) return 4.2;
  return 6.5; // Professional major baseline
}

